namespace QNB;

internal static class BrandAssets
{
    private const string HummingbirdPngBase64 = "[... ELLIPSIZATION ...]";

    public static Image CreateHummingbirdLogo(Color color)
    {
        using var stream = new MemoryStream(Convert.FromBase64String(HummingbirdPngBase64));
        using var source = Image.FromStream(stream);
        var bitmap = new Bitmap(source.Width, source.Height);

        using (var graphics = Graphics.FromImage(bitmap))
        {
            graphics.Clear(Color.Transparent);
            graphics.DrawImage(source, 0, 0, source.Width, source.Height);
        }

        for (var y = 0; y < bitmap.Height; y++)
        {
            for (var x = 0; x < bitmap.Width; x++)
            {
                var pixel = bitmap.GetPixel(x, y);
                if (pixel.A > 15)
                    bitmap.SetPixel(x, y, Color.FromArgb(pixel.A, color));
            }
        }

        return bitmap;
    }
}
